import * as React from "react"
import { useState, useEffect } from "react"
import { graphql } from "gatsby"
import { GatsbyImage, getImage, IGatsbyImageData } from "gatsby-plugin-image"

import "../scss/main.scss"

import Header from "../components/Header"

interface SlideNode {
  name: string
  childImageSharp: {
    gatsbyImageData: IGatsbyImageData
  }
}

interface PageProps {
  data: {
    allFile: {
      nodes: SlideNode[]
    }
  }
}

const Index: React.FC<PageProps> = ({ data }) => {
  const slides = data.allFile.nodes
  const [currentSlide, setCurrentSlide] = useState(0)
  const [isAutoPlaying, setIsAutoPlaying] = useState(true)

  useEffect(() => {
    if (!isAutoPlaying || slides.length === 0) return

    const interval = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % slides.length)
    }, 5000)

    return () => clearInterval(interval)
  }, [isAutoPlaying, slides.length])

  const goToSlide = (index: number) => {
    setCurrentSlide(index)
    setIsAutoPlaying(false)
  }

  const nextSlide = () => {
    setCurrentSlide((prev) => (prev + 1) % slides.length)
    setIsAutoPlaying(false)
  }

  const prevSlide = () => {
    setCurrentSlide((prev) => (prev - 1 + slides.length) % slides.length)
    setIsAutoPlaying(false)
  }

  return (
    <div className="container">
      <Header />
      <div className="hero-slideshow">
        <div className="slideshow-container">
          {slides.map((slide, index) => {
            const image = getImage(slide.childImageSharp.gatsbyImageData)
            return (
              <div
                key={slide.name}
                className={`slide ${index === currentSlide ? 'active' : ''}`}
              >
                {image && (
                  <GatsbyImage
                    image={image}
                    alt={slide.name}
                    className="slide-image"
                  />
                )}
              </div>
            )
          })}
        </div>

        <button className="slide-nav prev" onClick={prevSlide} aria-label="Previous slide">
          &larr;
        </button>
        <button className="slide-nav next" onClick={nextSlide} aria-label="Next slide">
          &rarr;
        </button>

        <div className="slide-indicators">
          {slides.map((_, index) => (
            <button
              key={index}
              className={`indicator ${index === currentSlide ? 'active' : ''}`}
              onClick={() => goToSlide(index)}
              aria-label={`Go to slide ${index + 1}`}
            />
          ))}
        </div>
      </div>
    </div>
  )
}

export const query = graphql`
  query IndexSlidesQuery {
    allFile(
      filter: { sourceInstanceName: { eq: "slides" } }
      sort: { name: ASC }
    ) {
      nodes {
        name
        childImageSharp {
          gatsbyImageData(
            layout: FULL_WIDTH
            placeholder: BLURRED
            quality: 90
          )
        }
      }
    }
  }
`

export default Index
